// Pointer Events: one active finger, capture, cancellation and canvas-local coordinates.
export function canvasPoint(canvas,event){const r=canvas.getBoundingClientRect(),width=r.width??r.right-r.left,height=r.height??r.bottom-r.top;if(!(width>0&&height>0))return null;const x=(event.clientX-r.left)/width,y=(event.clientY-r.top)/height;if(!Number.isFinite(x)||!Number.isFinite(y)||x<0||x>1||y<0||y>1)return null;return{x:x*2-1,y:1-y*2};}
export function bindWorldTap(canvas,tap,begin=()=>{},drag=null){let active=null;const id=e=>e.pointerId??1;function clear(){const p=active;active=null;if(p?.dragging)drag?.end?.();if(p)try{canvas.releasePointerCapture?.(p.id);}catch{}}
canvas.addEventListener('pointerdown',e=>{if(e.isPrimary===false||active&&active.id!==id(e)){clear();return;}if(e.pointerType==='mouse'&&e.button!==undefined&&e.button!==0)return;e.preventDefault?.();begin();active={id:id(e),x:e.clientX,y:e.clientY,moved:false,touch:e.pointerType==='touch'||e.pointerType==='pen',dragging:false,limit:e.pointerType==='touch'||e.pointerType==='pen'?28:14};try{canvas.setPointerCapture?.(active.id);}catch{}},{passive:false});
canvas.addEventListener('pointermove',e=>{if(!active||id(e)!==active.id)return;const dx=e.clientX-active.x,dy=e.clientY-active.y;if(Math.hypot(dx,dy)>active.limit){active.moved=true;if(active.touch&&!active.dragging&&drag?.canStart?.()){active.dragging=true;drag.start?.(active.x,active.y);}}if(active.dragging){e.preventDefault?.();drag.move?.(dx,dy);}},{passive:false});
canvas.addEventListener('pointerup',e=>{if(!active||active.id!==id(e))return;const p=active,valid=!p.moved&&Math.hypot(e.clientX-p.x,e.clientY-p.y)<=p.limit;clear();e.preventDefault?.();if(valid&&canvasPoint(canvas,e))tap(e);},{passive:false});
canvas.addEventListener('pointercancel',clear);canvas.addEventListener('lostpointercapture',e=>{if(active&&id(e)===active.id)clear();});return clear;}
